import "dotenv/config";
import { PrismaMariaDb } from "@prisma/adapter-mariadb";
import { PrismaClient } from "@prisma/client";

const adapter = new PrismaMariaDb({
  host: process.env.DATABASE_HOST!,
  user: process.env.DATABASE_USER!,
  password: process.env.DATABASE_PASSWORD!,
  database: process.env.DATABASE_NAME!,
  port: parseInt(process.env.DATABASE_PORT ?? "3306", 10),
  connectionLimit: process.env.NODE_ENV === "production" ? 10 : 5,
});

const globalForPrisma = globalThis as unknown as { prisma: PrismaClient };

// Force a new instance if the cached one is missing the 'document' model
const useCached = globalForPrisma.prisma && (globalForPrisma.prisma as any).document;

export const prisma = useCached ? globalForPrisma.prisma : new PrismaClient({ adapter });

if (process.env.NODE_ENV !== "production") {
  globalForPrisma.prisma = prisma;
}
